import{c as e,Q as r,j as t,m as n}from"./chunks/framework.BPKcPtvA.js";const m=JSON.parse('{"title":"Transformer 架构详解","description":"","frontmatter":{},"headers":[],"relativePath":"02-transformers/transformer-mechanics.md","filePath":"02-transformers/transformer-mechanics.md"}'),s={name:"02-transformers/transformer-mechanics.md"};function o(l,a,d,i,c,p){return r(),t("div",null,[...a[0]||(a[0]=[n(`<h1 id="transformer-架构详解" tabindex="-1">Transformer 架构详解 <a class="header-anchor" href="#transformer-架构详解" aria-label="Permalink to &quot;Transformer 架构详解&quot;">​</a></h1><blockquote><p>自注意力机制与位置编码 —— 现代大模型的基石</p></blockquote><h2 id="为什么需要-transformer" tabindex="-1">为什么需要 Transformer？ <a class="header-anchor" href="#为什么需要-transformer" aria-label="Permalink to &quot;为什么需要 Transformer？&quot;">​</a></h2><p>在 Transformer 出现之前，序列建模依赖于 RNN/LSTM 的循环结构，存在两个根本性局限：</p><ol><li><strong>串行计算</strong>：无法并行化，训练效率低</li><li><strong>长程依赖衰减</strong>：梯度在长序列中消失或爆炸</li></ol><p>Transformer 通过<strong>自注意力机制</strong>一次性解决了这两个问题。</p><h2 id="自注意力机制" tabindex="-1">自注意力机制 <a class="header-anchor" href="#自注意力机制" aria-label="Permalink to &quot;自注意力机制&quot;">​</a></h2><p>自注意力（Self-Attention）的核心思想：让序列中的每个位置都直接与所有其他位置交互：</p><p>$$ \\text{Attention}(Q, K, V) = \\text{softmax}\\left(\\frac{QK^T}{\\sqrt{d_k}}\\right)V $$</p><h3 id="qkv-三元组" tabindex="-1">QKV 三元组 <a class="header-anchor" href="#qkv-三元组" aria-label="Permalink to &quot;QKV 三元组&quot;">​</a></h3><ul><li><strong>Q (Query)</strong>：「我在找什么？」</li><li><strong>K (Key)</strong>：「我有什么信息？」</li><li><strong>V (Value)</strong>：「我的实际内容是什么？」</li></ul><p>三个矩阵均来自同一输入的线性投影。</p><h3 id="缩放因子-sqrt-d-k" tabindex="-1">缩放因子 $\\sqrt{d_k}$ <a class="header-anchor" href="#缩放因子-sqrt-d-k" aria-label="Permalink to &quot;缩放因子 $\\sqrt{d_k}$&quot;">​</a></h3><p>除以 $\\sqrt{d_k}$ 的原因：当 $d_k$ 较大时，点积 $QK^T$ 的方差会增大，导致 softmax 进入饱和区（梯度消失）。缩放保持了梯度的健康流动。</p><h2 id="多头注意力" tabindex="-1">多头注意力 <a class="header-anchor" href="#多头注意力" aria-label="Permalink to &quot;多头注意力&quot;">​</a></h2><p>单头注意力的表达能力有限。<strong>多头注意力（Multi-Head Attention）</strong> 并行运行多个注意力头，每个头关注不同的表示子空间：</p><p>$$ \\text{MultiHead}(Q, K, V) = \\text{Concat}(\\text{head}_1, \\ldots, \\text{head}_h)W^O $$</p><h2 id="位置编码" tabindex="-1">位置编码 <a class="header-anchor" href="#位置编码" aria-label="Permalink to &quot;位置编码&quot;">​</a></h2><p>注意力机制本身是<strong>置换不变</strong>的 —— 打乱输入顺序，输出不变。位置编码（Positional Encoding）为模型注入序列顺序信息。</p><h3 id="正弦位置编码-原始方案" tabindex="-1">正弦位置编码（原始方案） <a class="header-anchor" href="#正弦位置编码-原始方案" aria-label="Permalink to &quot;正弦位置编码（原始方案）&quot;">​</a></h3><p>$$ PE_{(pos, 2i)} = \\sin\\left(\\frac{pos}{10000^{2i/d_{model}}}\\right) $$ $$ PE_{(pos, 2i+1)} = \\cos\\left(\\frac{pos}{10000^{2i/d_{model}}}\\right) $$</p><h3 id="rope-旋转位置编码" tabindex="-1">RoPE（旋转位置编码） <a class="header-anchor" href="#rope-旋转位置编码" aria-label="Permalink to &quot;RoPE（旋转位置编码）&quot;">​</a></h3><p>现代 LLM（LLaMA、Qwen 等）普遍采用的方案，通过旋转矩阵将位置信息编码到注意力计算中，具有良好的外推性。</p><h2 id="transformer-完整架构" tabindex="-1">Transformer 完整架构 <a class="header-anchor" href="#transformer-完整架构" aria-label="Permalink to &quot;Transformer 完整架构&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>输入 → [Embedding + Positional Encoding]</span></span>
<span class="line"><span>    → [Multi-Head Self-Attention]</span></span>
<span class="line"><span>    → [Add &amp; Norm]</span></span>
<span class="line"><span>    → [Feed-Forward Network]</span></span>
<span class="line"><span>    → [Add &amp; Norm]</span></span>
<span class="line"><span>    → 输出</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h3 id="encoder-decoder-vs-decoder-only" tabindex="-1">Encoder-Decoder vs Decoder-Only <a class="header-anchor" href="#encoder-decoder-vs-decoder-only" aria-label="Permalink to &quot;Encoder-Decoder vs Decoder-Only&quot;">​</a></h3><table tabindex="0"><thead><tr><th>架构类型</th><th>代表模型</th><th>特点</th></tr></thead><tbody><tr><td>Encoder-Decoder</td><td>T5, BART</td><td>适合 seq2seq 任务</td></tr><tr><td>Encoder-Only</td><td>BERT</td><td>适合理解任务</td></tr><tr><td>Decoder-Only</td><td>GPT 系列</td><td>因果注意力掩码，自回归生成</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">关键演进</p><p>现代 LLM 几乎全部采用 Decoder-Only 架构，因为因果注意力掩码天然适配自回归语言建模，且训练效率最高。</p></div>`,28)])])}const u=e(s,[["render",o]]);export{m as __pageData,u as default};
